import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"渲染管线","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/rendering.md","filePath":"zh/guide/rendering.md","lastUpdated":1786971590000}'),t={name:"zh/guide/rendering.md"};function d(l,e,n,c,h,s){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="渲染管线" tabindex="-1">渲染管线 <a class="header-anchor" href="#渲染管线" aria-label="Permalink to &quot;渲染管线&quot;">​</a></h1><h2 id="两层架构" tabindex="-1">两层架构 <a class="header-anchor" href="#两层架构" aria-label="Permalink to &quot;两层架构&quot;">​</a></h2><ul><li><strong>Application 层</strong>：构建 Widget 树，Taitank 计算布局，录制 RenderCommand 到 RenderContext</li><li><strong>Render 层</strong>：从 SPSC 环形队列消费命令，tgfx 执行绘制</li></ul><h2 id="渲染命令" tabindex="-1">渲染命令 <a class="header-anchor" href="#渲染命令" aria-label="Permalink to &quot;渲染命令&quot;">​</a></h2><p>RenderCommand 支持以下类型：</p><ul><li><code>kBeginFrame</code> / <code>kEndFrame</code>：帧边界</li><li><code>kDrawRect</code>：绘制矩形</li><li><code>kDrawRoundedRect</code>：绘制圆角矩形</li><li><code>kDrawText</code>：绘制文本（UTF-8）</li><li><code>kClipRect</code>：设置裁剪区域</li><li><code>kTranslate</code>：平移变换</li><li><code>kSave</code> / <code>kRestore</code>：保存/恢复渲染状态</li></ul><h2 id="桌面端" tabindex="-1">桌面端 <a class="header-anchor" href="#桌面端" aria-label="Permalink to &quot;桌面端&quot;">​</a></h2><p>通过 GLFW 创建窗口与 OpenGL 上下文，tgfx 渲染到 GL framebuffer，最后交换缓冲区。</p><h2 id="移动端" tabindex="-1">移动端 <a class="header-anchor" href="#移动端" aria-label="Permalink to &quot;移动端&quot;">​</a></h2><p>tgfx 直接渲染到平台提供的 Surface：</p><ul><li>Android：<code>ANativeWindow*</code></li><li>iOS：<code>CAMetalLayer*</code> / <code>CAEAGLLayer*</code></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./architecture">架构</a></li><li><a href="./cross-platform">跨平台</a></li></ul>',13)])])}const m=a(t,[["render",d]]);export{f as __pageData,m as default}